"""
有向グラフの閉路検出 & トポロジカルソート (Cycle Detection & Topological Sort)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- has_cycle(n, g): 有向グラフに閉路（サイクル）が存在するか判定。
  Kahnのアルゴリズム (入次数管理 BFS) により O(V + E) で非再帰かつ超高速。
- find_cycle(n, g): 閉路が存在する場合、閉路を構成する頂点列 (u1 -> u2 -> ... -> u1) を復元して返す。
  存在しない場合は空リスト [] を返す。

【引数】
- n: 頂点数 (0 ~ n-1)
- g: 隣接リスト [[v1, v2, ...], ...] (有向辺 u -> v)
"""

from collections import deque

# https://github.com/ddfkit/acsampl/blob/main/cycle.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def topo_sort(n,g):
    deg=[0]*n
    for es in g:
        for v in es:deg[v]+=1
    q=deque([i for i in range(n) if not deg[i]]);res=[]
    while q:
        u=q.popleft();res.append(u)
        for v in g[u]:
            deg[v]-=1
            if not deg[v]:q.append(v)
    return res if len(res)==n else []

# https://github.com/ddfkit/acsampl/blob/main/cycle.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def find_cycle(n,g):
    vis=[0]*n;par=[-1]*n
    for s in range(n):
        if vis[s]:continue
        st=[(s,0)]
        while st:
            u,it=st.pop()
            if not it:
                vis[u]=1;st.append((u,1))
                for v in g[u]:
                    if vis[v]==1:
                        cy=[v];cur=u
                        while cur!=v:cy.append(cur);cur=par[cur]
                        cy.append(v);return cy[::-1]
                    elif not vis[v]:par[v]=u;st.append((v,0))
            else:vis[u]=2
    return []

if __name__ == "__main__":
    g_dag = [[1, 2], [3], [3], []]
    order = topo_sort(4, g_dag)
    assert len(order) == 4

    g_cy = [[1], [2], [3], [1]]
    assert topo_sort(4, g_cy) == []
    cy = find_cycle(4, g_cy)
    assert len(cy) >= 3 and cy[0] == cy[-1]
    print("cycle.py: tests passed!")
